import { test, expect } from '@playwright/test';

test.describe('Session Expired Message on Token Timeout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display session expired message when token times out', async ({ page }) => {
    // Setup: Mock API response to simulate token expiration
    await page.route('**/api/auth/token', async (route) => {
      await route.abort('failed');
    });

    // Intercept the initial token request
    await page.route('**/api/auth/token', async (route) => {
      await route.continue();
    });

    // Verify initial token is displayed
    const tokenDisplay = page.getByText('Token: abc123');
    await expect(tokenDisplay).toBeVisible();

    // Verify session expired message is not visible initially
    const sessionExpiredMessage = page.getByText('Session expired');
    await expect(sessionExpiredMessage).not.toBeVisible();

    // Verify session expiration button is visible
    const sessionExpireButton = page.getByRole('button', { name: /expire session/i });
    await expect(sessionExpireButton).toBeVisible();

    // Click session expire button to trigger token expiration
    await sessionExpireButton.click();

    // Wait for token expiration response
    await page.waitForTimeout(100);

    // Verify session expired message is now visible
    await expect(sessionExpiredMessage).toBeVisible();

    // Verify user is redirected to login page
    const loginPage = page.getByRole('dialog', { name: /login/i });
    await expect(loginPage).toBeVisible();

    // Verify login form is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText('Session expired');
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry session/i });
    await expect(retryButton).toBeVisible();
  });

